let data=structuredClone(DEMO),managed=structuredClone(DEMO),currentUser=null,csrfToken='',menuOpen=false,searchOpen=false,currentFilter='Semua',listingQuery='',adminTab='articles',ticker=0,interval=null,tickerPaused=false,lastRoute='';
const save=()=>true;
async function requestAPI(url,options={}){const headers={...(options.body&&! (options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...(options.method&&options.method!=='GET'&&csrfToken?{'X-CSRF-Token':csrfToken}:{}),...options.headers};let r=await fetch(url,{...options,headers,credentials:'same-origin'});let result=await r.json().catch(()=>({}));if(!r.ok)throw Error(result.error||'Permintaan gagal ('+r.status+')');return result}
async function refreshContent(){let publicData=await requestAPI('/api/public');data=publicData.items;if(currentUser&&['admin','editor'].includes(currentUser.role)){let m=await requestAPI('/api/manage');managed=m.items}else managed=structuredClone(data)}
async function refreshAuth(){const x=await requestAPI('/api/me');currentUser=x.user;csrfToken=x.csrf||''}
async function initialize(){try{await refreshAuth();await refreshContent();route()}catch(err){route();const n=document.querySelector('#app');if(n)n.insertAdjacentHTML('afterbegin',`<div class="server-warning" role="alert">Server data tidak terhubung. Pastikan website dibuka melalui <strong>127.0.0.1:8097</strong> dan server Node.js sedang berjalan. ${esc(err.message)}</div>`)}}
async function loadRequests(){try{let result=await requestAPI('/api/requests');return result.requests}catch(err){toast(err.message);return []}}
function toast(message){let n=document.querySelector('#toast');if(!n)return;n.textContent=message;n.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove('show'),3800)}
const brandIcon=`<svg class="brand-mark" viewBox="0 0 52 52" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="3"><path d="M26 4 34 13 26 22 18 13 26 4ZM26 30l8 9-8 9-8-9 8-9ZM4 26l9-8 9 8-9 8-9-8ZM30 26l9-8 9 8-9 8-9-8Z"/><circle cx="26" cy="26" r="5" fill="currentColor" stroke="none"/><path d="M26 0v10M26 42v10M0 26h10m32 0h10"/></g></svg>`;
