if(action==='admin-tab'){adminTab=el.dataset.kind;document.querySelector('#app').innerHTML=header('#/admin')+admin()+footer()+modalShell();installMotion();afterRoute();return}
if(action==='add'||action==='edit'){if(!currentUser||!['admin','editor'].includes(currentUser.role))return toast('Masuk sebagai pengurus terlebih dahulu.');openDialog(editor(el.dataset.kind,el.dataset.id||''))}
if(action==='delete'){let kind=el.dataset.kind,id=el.dataset.id,item=managed[kind]?.find(x=>x.id===id);if(item&&confirm(`Hapus secara permanen: ${item.title}?\nTindakan ini tidak dapat dibatalkan.`)){try{await requestAPI('/api/manage/'+kind+'/'+id,{method:'DELETE'});await refreshContent();route();toast('Konten telah dihapus dari server.')}catch(err){toast(err.message)}}}
